:root{color-scheme:dark;--bg:#101114;--panel:#191a1f;--panel-2:#202127;--line:#303137;--muted:#85858f;--text:#f4f3ef;--lime:#d2f36b;--pink:#fb7185;--font:'Space Grotesk',sans-serif;--mono:'DM Mono',monospace}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 75% 4%,rgba(210,243,107,.055),transparent 30%),var(--bg);color:var(--text);font-family:var(--font);min-height:100vh}.app-shell{max-width:1160px;margin:0 auto;padding:0 40px}.topbar{height:74px;border-bottom:1px solid #ffffff13;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;font-size:16px;letter-spacing:1.6px;font-weight:700;color:var(--text);text-decoration:none}.brand-mark{background:var(--lime);color:#171a0d;border-radius:7px;width:28px;height:28px;display:grid;place-items:center;font-size:17px;font-weight:700}.brand-dot{color:var(--lime)}.top-meta,.eyebrow,.optional-tag,.round-count,.tempo-status,.bpm-unit,.prompt-topline,.rhyme-heading,.tempo-controls>label,.text-button,.session-stats div span,.page-footer,.local-badge{font-family:var(--mono);letter-spacing:1px}.top-meta{color:#8e8f91;font-size:10px;display:flex;align-items:center;gap:8px}.live-dot,.status-dot,.local-badge i{width:7px;height:7px;background:var(--lime);border-radius:50%;box-shadow:0 0 10px #d2f36b65}.icon-button{width:34px;height:34px;background:#202127;border:1px solid var(--line);border-radius:9px;color:#c5c6cb;cursor:pointer;font-size:19px}.icon-button.active{color:var(--lime);border-color:#d2f36b70}.intro{padding:42px 0 30px}.eyebrow{font-size:9px;color:#a6a6ad;margin:0 0 11px}.intro h1{font-size:clamp(34px,5vw,47px);letter-spacing:-2.3px;line-height:1;margin:0}.intro h1 span{color:var(--lime)}.intro-copy{margin:12px 0 0;color:#96969e;font-size:13px;max-width:540px;line-height:1.6}.studio-grid{display:grid;grid-template-columns:minmax(0,1.48fr) minmax(310px,.82fr);gap:18px;align-items:stretch}.left-column{display:flex;flex-direction:column;gap:18px}.card{background:linear-gradient(145deg,#1b1c21,#18191e);border:1px solid #ffffff10;border-radius:14px;padding:20px;box-shadow:0 16px 38px #00000014}.card-heading{display:flex;justify-content:space-between;align-items:flex-start}.card-heading h2{margin:0;font-size:17px;letter-spacing:-.4px}.optional-tag,.round-count{border:1px solid #ffffff18;border-radius:30px;padding:6px 9px;font-size:8px;color:#999aa2}.youtube-form{display:flex;gap:8px;margin-top:16px}.youtube-form input{flex:1;min-width:0;background:#111216;border:1px solid #35363c;border-radius:8px;padding:0 12px;color:var(--text);font:12px var(--font);outline:none}.youtube-form input:focus{border-color:var(--lime)}.youtube-form input::placeholder{color:#70717a}.button{border:0;border-radius:8px;padding:0 14px;font:700 10px var(--mono);letter-spacing:.5px;cursor:pointer}.button-light{background:#e8e8e3;color:#17181b;height:38px}.button-light:hover{background:var(--lime)}.helper-text{font-size:10px;color:#82838b;margin:10px 0 0;line-height:1.5}.player-frame{position:relative;margin-top:14px;border-radius:9px;overflow:hidden;background:#0d0e11;aspect-ratio:16/9}.player-frame[hidden]{display:none}.player-frame iframe{width:100%;height:100%;border:0}.player-close{position:absolute;right:7px;top:7px;width:27px;height:27px;border:0;border-radius:50%;background:#000a;color:white;font-size:20px;cursor:pointer}.challenge-card{flex:1}.mode-switch{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:17px 0}.mode-button{display:flex;align-items:center;text-align:left;gap:10px;padding:11px 12px;background:#202127;border:1px solid #ffffff0d;border-radius:9px;color:#b8b8bf;cursor:pointer;transition:.18s}.mode-button:hover{border-color:#ffffff32}.mode-button.active{border-color:#d2f36b66;background:#25291e;color:#f4f3ef}.mode-icon{display:grid;place-items:center;width:34px;height:34px;border-radius:8px;background:#2c2d33;color:var(--lime);font-weight:700;font-size:16px}.mode-button strong,.mode-button small{display:block}.mode-button strong{font-size:11px}.mode-button small{font-size:9px;color:#85858e;margin-top:3px}.prompt-panel{padding:17px 18px 14px;border-radius:10px;background:linear-gradient(110deg,#25271f,#20211f);border:1px solid #d2f36b28;min-height:114px;position:relative;overflow:hidden}.prompt-panel:after{content:'';position:absolute;right:-40px;top:-62px;width:175px;height:175px;border:1px solid #d2f36b15;border-radius:50%;box-shadow:0 0 0 20px #d2f36b08,0 0 0 40px #d2f36b05;pointer-events:none}.prompt-topline{display:flex;justify-content:space-between;color:#a0a18d;font-size:8px}.prompt-index{color:#73746c}.prompt-word{font-size:32px;line-height:1.1;letter-spacing:1px;font-weight:700;color:var(--lime);margin-top:11px;transition:transform .16s,opacity .16s}.prompt-word.pop{animation:pop .28s ease}@keyframes pop{50%{transform:scale(1.045);text-shadow:0 0 22px #d2f36b70}}.prompt-hint{margin:5px 0 0;font-size:10px;color:#a1a198}.rhyme-area{margin-top:16px}.rhyme-heading{font-size:8px;color:#a3a3ab;display:flex;justify-content:space-between}.reveal-note{color:#71727a;font-size:8px}.rhyme-list{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:9px}.rhyme-chip{min-height:33px;padding:8px 4px;display:grid;place-items:center;background:#24252b;border:1px solid #ffffff09;border-radius:7px;color:#d1d1d2;font-size:10px;font-weight:600;opacity:0;transform:translateY(4px);transition:opacity .2s,transform .2s;text-align:center}.rhyme-chip.visible{opacity:1;transform:translateY(0)}.rhyme-chip.empty-chip{opacity:1;color:#55565f;background:#202126}.round-footer{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-top:13px}.round-footer>span{font-size:9px;color:#85858e}.hit-button{border:1px solid #d2f36b38;background:#d2f36b12;border-radius:7px;color:var(--lime);padding:8px 10px;font:700 8px var(--mono);letter-spacing:.3px;white-space:nowrap;cursor:pointer}.hit-button:disabled{opacity:.36;cursor:not-allowed}.tempo-card{display:flex;flex-direction:column;align-items:stretch;position:relative;overflow:hidden}.tempo-status{font-size:8px;display:flex;gap:6px;align-items:center;color:#999aa0}.status-dot{background:#777;box-shadow:none;width:6px;height:6px}.tempo-status.running .status-dot{background:var(--lime);box-shadow:0 0 9px #d2f36b}.bpm-wrap{display:flex;align-items:baseline;gap:9px;margin:22px 0 0;justify-content:center}.bpm-value{font-size:76px;font-weight:600;letter-spacing:-6px;line-height:1}.bpm-unit{font-size:10px;color:#898991}.tempo-caption{text-align:center;color:#85858d;font-size:10px;margin:3px 0 20px;min-height:15px}.beat-track{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:0 1px 21px}.beat{height:38px;border:1px solid #ffffff12;background:#202127;border-radius:7px;display:grid;place-items:center;color:#777881;font:11px var(--mono);transition:.08s}.beat.active{background:#d2f36b;color:#15170f;border-color:var(--lime);transform:translateY(-2px);box-shadow:0 5px 16px #d2f36b24}.beat.sub-beat{border-color:#d2f36b70;background:#d2f36b25;color:var(--lime)}.tap-button{align-self:center;position:relative;width:min(190px,70%);aspect-ratio:1;border-radius:50%;border:1px solid #d2f36b81;background:radial-gradient(circle at 50% 40%,#343927,#25281e 68%,#1b1d18);color:var(--lime);cursor:pointer;display:flex;align-items:center;justify-content:center;flex-direction:column;box-shadow:0 0 0 9px #d2f36b09,0 0 0 18px #d2f36b05,inset 0 0 35px #d2f36b0d;transition:transform .1s,box-shadow .2s;touch-action:manipulation;user-select:none}.tap-button:active,.tap-button.pulse{transform:scale(.96);box-shadow:0 0 0 12px #d2f36b13,0 0 35px #d2f36b19,inset 0 0 50px #d2f36b18}.tap-label{font-size:28px;font-weight:700;letter-spacing:2px;z-index:1}.tap-subtitle{font:8px var(--mono);letter-spacing:1.4px;color:#b3c58a;margin-top:4px;z-index:1}.tap-rings i{position:absolute;inset:15px;border:1px solid #d2f36b0d;border-radius:50%}.tap-rings i:nth-child(2){inset:27px}.tap-rings i:nth-child(3){inset:39px}.tempo-controls{margin-top:22px;display:flex;align-items:center;justify-content:space-between}.tempo-controls>label{font-size:8px;color:#96969e}.segmented{display:flex;background:#111216;padding:3px;border-radius:7px;gap:2px}.segmented button{border:0;background:transparent;color:#8e8f96;font:9px var(--mono);padding:6px 11px;border-radius:5px;cursor:pointer}.segmented button.selected{background:#34372a;color:var(--lime)}.text-button{align-self:center;background:none;border:0;color:#85858d;font-size:8px;margin:16px auto 15px;cursor:pointer}.text-button:hover{color:var(--text)}.text-button span{margin-left:5px}.session-stats{margin-top:auto;border-top:1px solid #ffffff10;padding-top:14px;display:grid;grid-template-columns:repeat(3,1fr);text-align:center}.session-stats div+div{border-left:1px solid #ffffff10}.session-stats strong{display:block;font-size:18px}.session-stats div span{display:block;color:#82838a;font-size:7px;margin-top:3px}.tips-row{display:flex;align-items:center;gap:12px;border:1px solid #ffffff0e;background:#17181d;border-radius:10px;padding:14px 17px;margin-top:17px}.tip-icon{width:27px;height:27px;display:grid;place-items:center;border-radius:8px;background:#d2f36b15;color:var(--lime);font-size:16px}.tips-row p{margin:0;display:flex;flex-direction:column;gap:3px;flex:1}.tips-row p strong{font-size:10px}.tips-row p span{font-size:9px;color:#8c8d94}.local-badge{display:flex;align-items:center;gap:6px;font-size:8px;color:#92939a}.local-badge i{width:5px;height:5px}.page-footer{display:flex;justify-content:space-between;color:#62636b;font-size:8px;padding:20px 2px 25px}.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,20px);padding:10px 14px;border-radius:8px;background:#e8e8e3;color:#151619;font-size:11px;font-weight:600;opacity:0;pointer-events:none;transition:.2s;z-index:10;box-shadow:0 6px 24px #0008}.toast.show{opacity:1;transform:translate(-50%,0)}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}body.mode-double{--lime:#fb7185}body.mode-double .prompt-panel{background:linear-gradient(110deg,#2c2024,#222022);border-color:#fb718538}body.mode-double .mode-button.active{border-color:#fb718566;background:#2a2024}body.mode-double .tap-button{border-color:#fb71857a;background:radial-gradient(circle at 50% 40%,#3b292c,#281f21 68%,#1d1819)}body.mode-double .mode-icon{color:#fb7185}
@media(min-width:1000px){.tempo-card{min-height:548px}.challenge-card{min-height:390px}}@media(max-width:760px){.app-shell{padding:0 22px}.studio-grid{grid-template-columns:minmax(0,1fr) minmax(275px,.78fr);gap:12px}.left-column{gap:12px}.card{padding:17px}.intro{padding:35px 0 24px}.prompt-word{font-size:27px}.round-footer{align-items:flex-start;flex-direction:column}.hit-button{align-self:flex-end}.tempo-card{padding:17px}.bpm-value{font-size:66px}}@media(max-width:590px){.app-shell{padding:0 16px}.topbar{height:62px}.top-meta{font-size:8px}.intro{padding:29px 0 21px}.intro h1{font-size:38px}.intro-copy{font-size:12px}.studio-grid{grid-template-columns:1fr}.tempo-card{order:-1;min-height:unset}.bpm-wrap{margin-top:16px}.bpm-value{font-size:61px}.tempo-caption{margin-bottom:13px}.beat-track{margin-bottom:15px}.tap-button{width:145px}.tempo-controls{margin-top:18px}.text-button{margin:13px auto}.session-stats{padding-top:11px}.left-column{gap:12px}.tips-row{align-items:flex-start;flex-wrap:wrap}.tips-row p{min-width:calc(100% - 50px)}.local-badge{margin-left:39px}.page-footer{font-size:7px}.round-footer{flex-direction:row;align-items:center}.round-footer>span{max-width:55%}.hit-button{align-self:auto}.card-heading h2{font-size:16px}}@media(max-width:370px){.app-shell{padding:0 11px}.card{padding:14px}.mode-button{padding:9px 7px;gap:7px}.mode-button strong{font-size:10px}.mode-button small{font-size:8px}.rhyme-chip{font-size:9px}.prompt-word{font-size:24px}.round-footer>span{font-size:8px}.hit-button{font-size:7px;padding:8px 7px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;transition-duration:.01ms!important}}

(() => {
  'use strict';

  const $ = (selector) => document.querySelector(selector);
  const ui = {
    tap: $('#tap-button'), bpm: $('#bpm-value'), tempoStatus: $('#tempo-status'),
    tempoCaption: $('#tempo-caption'), beatBoxes: [...document.querySelectorAll('.beat')],
    subdivisionButtons: [...document.querySelectorAll('[data-subdivision]')],
    modeButtons: [...document.querySelectorAll('[data-mode]')], round: $('#round-count'),
    promptLabel: $('#prompt-label'), promptIndex: $('#prompt-index'), promptWord: $('#prompt-word'),
    promptHint: $('#prompt-hint'), rhymeList: $('#rhyme-list'), revealNote: $('#reveal-note'),
    instruction: $('#instruction'), hit: $('#hit-button'), streak: $('#streak-value'),
    hits: $('#hits-value'), best: $('#best-value'), reset: $('#reset-button'),
    sound: $('#sound-toggle'), form: $('#youtube-form'), url: $('#youtube-url'),
    playerFrame: $('#player-frame'), player: $('#youtube-player'),
    playerStatus: $('#youtube-status'), closePlayer: $('#close-player'), toast: $('#toast'),
  };
  if (Object.values(ui).some((element) => !element)) return;

  const STORAGE_KEY = 'rapea-session-v1';
  const PROMPTS = {
    esdrujulas: [
      { word: 'MÁGICO', hint: 'Convertí una escena del barrio en algo imposible.', rhymes: ['trágico', 'clásico', 'básico', 'simbólico'] },
      { word: 'ELÉCTRICO', hint: 'Que se sienta la energía en cada barra.', rhymes: ['métrico', 'simétrico', 'excéntrico', 'geométrico'] },
      { word: 'RÁPIDO', hint: 'Una respuesta veloz, pero que diga algo.', rhymes: ['válido', 'cálido', 'pálido', 'sólido'] },
      { word: 'CÁMARA', hint: 'Contá lo que pasa como si filmaras una escena.', rhymes: ['lámpara', 'pájara', 'máscara', 'náufraga'] },
      { word: 'PÚBLICO', hint: 'Hablale a la plaza como si fuera una sola voz.', rhymes: ['músico', 'único', 'rústico', 'lúdico'] },
      { word: 'LÓGICA', hint: 'Dale vuelta a una idea con un remate inesperado.', rhymes: ['simbólica', 'metáfora', 'histórica', 'caótica'] },
      { word: 'BRÚJULA', hint: 'Perdete un segundo y encontrá tu propio norte.', rhymes: ['burbuja', 'aguja', 'dibujan', 'empujan'] },
      { word: 'ESDRÚJULA', hint: 'Jugá con el acento y caé firme en el compás.', rhymes: ['película', 'partícula', 'ridícula', 'minúscula'] },
    ],
    doble: [
      { word: 'EL BONDI', hint: 'Doble tempo: cada pulso tiene dos espacios.', rhymes: ['escondí', 'seguí', 'compartí', 'por aquí'] },
      { word: 'LA VEREDA', hint: 'Meté dos sílabas por pulso y pintá la escena.', rhymes: ['moneda', 'rueda', 'queda', 'vereda'] },
      { word: 'UN MATE', hint: 'Doble tempo: mantené el aire y cambiá el remate.', rhymes: ['debate', 'late', 'rescate', 'combate'] },
      { word: 'LA PLAZA', hint: 'Hacé que responda el barrio, sin perder el pulso.', rhymes: ['amenaza', 'abraza', 'terraza', 'calabaza'] },
      { word: 'EL POTRERO', hint: 'Dos golpes por pulso: jugá la barra de primera.', rhymes: ['compañero', 'sincero', 'sendero', 'aguacero'] },
      { word: 'EL SUBTE', hint: 'Doble velocidad, con las palabras bien claras.', rhymes: ['rebote', 'bigote', 'fuerte', 'norte'] },
      { word: 'EL BARRIO', hint: 'Contá una historia corta que tenga principio y giro.', rhymes: ['escenario', 'diario', 'horario', 'adversario'] },
      { word: 'LA ESQUINA', hint: 'Doblá el ritmo y dejá que la imagen se defina.', rhymes: ['neblina', 'rutina', 'vecina', 'gasolina'] },
    ],
  };

  const saved = readProgress();
  const state = {
    mode: 'esdrujulas', subdivision: 1, tapTimes: [], intervals: [], bpm: null,
    running: false, timer: 0, tickTimerIds: new Set(), generation: 0,
    nextTickAt: 0, tickNumber: 0, roundNumber: 0, currentPrompt: null,
    rhymeRevealed: false, hitThisRound: false, streak: saved.streak,
    hits: saved.hits, best: saved.best, soundOn: false, audio: null,
    player: null, pendingMedia: null, apiState: 'idle', toastTimer: 0,
  };

  updateStats();
  setMode('esdrujulas');
  renderEmptyPrompt();
  setTempoReady(false);
  updateSoundButton();

  ui.tap.addEventListener('click', handleTap);
  ui.modeButtons.forEach((button) => button.addEventListener('click', () => setMode(button.dataset.mode)));
  ui.subdivisionButtons.forEach((button) => button.addEventListener('click', () => {
    state.subdivision = Number(button.dataset.subdivision);
    ui.subdivisionButtons.forEach((item) => {
      const selected = item === button;
      item.classList.toggle('selected', selected);
      item.setAttribute('aria-pressed', String(selected));
    });
    restartClockPhase();
  }));
  ui.hit.addEventListener('click', confirmHit);
  ui.reset.addEventListener('click', resetSession);
  ui.sound.addEventListener('click', toggleSound);
  ui.form.addEventListener('submit', handleYouTubeSubmit);
  ui.closePlayer.addEventListener('click', closeYouTubePlayer);

  function readProgress() {
    try {
      const value = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
      return {
        streak: safeCount(value.streak), hits: safeCount(value.hits),
        best: safeCount(value.best),
      };
    } catch (_) {
      return { streak: 0, hits: 0, best: 0 };
    }
  }

  function safeCount(value) {
    return Number.isSafeInteger(value) && value >= 0 ? Math.min(value, 999999) : 0;
  }

  function saveProgress() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({
        streak: state.streak, hits: state.hits, best: state.best,
      }));
    } catch (_) {
      // Private browsing or a full storage quota must not interrupt practice.
    }
  }

  function handleTap() {
    const now = performance.now();
    pulseTapButton();
    if (state.soundOn) resumeAudio();
    if (state.tapTimes.length && now - state.tapTimes[state.tapTimes.length - 1] > 2200) {
      state.tapTimes = [];
      state.intervals = [];
    }
    if (state.tapTimes.length) {
      const interval = now - state.tapTimes[state.tapTimes.length - 1];
      if (interval >= 250 && interval <= 1500) {
        state.intervals.push(interval);
        state.intervals = state.intervals.slice(-6);
        const estimate = estimateBpm(state.intervals);
        if (estimate) {
          state.bpm = estimate;
          ui.bpm.textContent = String(estimate);
          ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
          setTempoReady(true);
          startClock();
        }
      } else if (interval > 1500) {
        state.intervals = [];
      }
    }
    state.tapTimes.push(now);
    state.tapTimes = state.tapTimes.slice(-7);
    if (!state.bpm) {
      ui.tempoCaption.textContent = state.tapTimes.length > 1 ? 'Seguí tocando para fijar el pulso' : 'Tocá al ritmo de tu base';
    }
    if (navigator.vibrate) navigator.vibrate(8);
  }

  function estimateBpm(intervals) {
    if (!intervals.length) return null;
    const ordered = [...intervals].sort((a, b) => a - b);
    const middle = Math.floor(ordered.length / 2);
    const median = ordered.length % 2 ? ordered[middle] : (ordered[middle - 1] + ordered[middle]) / 2;
    const reliable = intervals.filter((value) => Math.abs(value - median) <= median * 0.18);
    const average = reliable.reduce((sum, value) => sum + value, 0) / reliable.length;
    return Math.max(40, Math.min(240, Math.round(60000 / average)));
  }

  function effectiveTempo() {
    return state.bpm ? state.bpm * (state.mode === 'doble' ? 2 : 1) : 0;
  }

  function setTempoReady(ready) {
    ui.tempoStatus.classList.toggle('running', ready && state.running);
    ui.tempoStatus.lastChild.textContent = ready ? (state.running ? 'EN MARCHA' : 'LISTO') : 'ESPERANDO';
  }

  function startClock() {
    if (!state.bpm || state.running) return;
    state.running = true;
    state.generation += 1;
    state.tickNumber = 0;
    state.nextTickAt = performance.now() + 70;
    setTempoReady(true);
    ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
    scheduleLoop(state.generation);
  }

  function scheduleLoop(generation) {
    if (!state.running || generation !== state.generation) return;
    const now = performance.now();
    const divisions = state.subdivision * (state.mode === 'doble' ? 2 : 1);
    const stepMs = 60000 / state.bpm / divisions;
    while (state.nextTickAt <= now + 100) {
      if (state.nextTickAt < now - stepMs) state.nextTickAt = now + 8;
      const scheduledAt = state.nextTickAt;
      const tick = state.tickNumber++;
      const beat = Math.floor(tick / divisions) % 4;
      const isAccent = tick % divisions === 0;
      queueTick(scheduledAt, beat, isAccent, generation);
      if (state.soundOn) scheduleClick(scheduledAt, isAccent);
      state.nextTickAt += stepMs;
    }
    state.timer = window.setTimeout(() => scheduleLoop(generation), 25);
  }

  function queueTick(time, beat, isAccent, generation) {
    const delay = Math.max(0, time - performance.now());
    const id = window.setTimeout(() => {
      state.tickTimerIds.delete(id);
      if (!state.running || generation !== state.generation) return;
      renderBeat(beat, isAccent);
      if (isAccent) onMainBeat(beat);
    }, delay);
    state.tickTimerIds.add(id);
  }

  function renderBeat(beat, isAccent) {
    ui.beatBoxes.forEach((box, index) => {
      box.classList.toggle('active', index === beat && isAccent);
      box.classList.toggle('sub-beat', index === beat && !isAccent);
    });
  }

  function onMainBeat(beat) {
    if (beat === 0) {
      state.roundNumber += 1;
      state.currentPrompt = choosePrompt(state.mode);
      state.rhymeRevealed = false;
      state.hitThisRound = false;
      ui.hit.disabled = true;
      ui.round.textContent = `RONDA ${String(state.roundNumber).padStart(2, '0')}`;
      ui.promptLabel.textContent = state.mode === 'esdrujulas' ? 'CONCEPTO · ACENTO EN LA ANTEPENÚLTIMA' : 'CONCEPTO · DOBLE TEMPO';
      ui.promptIndex.textContent = `#${String(state.roundNumber).padStart(2, '0')}`;
      ui.promptWord.textContent = state.currentPrompt.word;
      ui.promptWord.classList.remove('pop');
      void ui.promptWord.offsetWidth;
      ui.promptWord.classList.add('pop');
      ui.promptHint.textContent = state.currentPrompt.hint;
      ui.instruction.textContent = state.mode === 'doble' ? 'Doblá las sílabas; el remate llega en el pulso 3.' : 'En el 1, agarrá el concepto. En el 3, buscá el remate.';
      showEmptyRhymes();
    }
    if (beat === 2 && state.currentPrompt && !state.rhymeRevealed) revealRhymes();
  }

  function choosePrompt(mode) {
    const choices = PROMPTS[mode].filter((item) => item !== state.currentPrompt);
    return choices[Math.floor(Math.random() * choices.length)] || PROMPTS[mode][0];
  }

  function showEmptyRhymes() {
    ui.rhymeList.replaceChildren(...Array.from({ length: 4 }, () => {
      const chip = document.createElement('span');
      chip.className = 'rhyme-chip empty-chip';
      chip.textContent = '—';
      return chip;
    }));
    ui.revealNote.textContent = 'APARECE EN EL TIEMPO 3';
  }

  function revealRhymes() {
    state.rhymeRevealed = true;
    ui.rhymeList.replaceChildren(...state.currentPrompt.rhymes.map((word, index) => {
      const chip = document.createElement('span');
      chip.className = 'rhyme-chip';
      chip.textContent = word;
      chip.style.transitionDelay = `${index * 45}ms`;
      requestAnimationFrame(() => chip.classList.add('visible'));
      return chip;
    }));
    ui.revealNote.textContent = '¡REMATE A TU MANERA!';
    ui.hit.disabled = false;
  }

  function renderEmptyPrompt() {
    ui.round.textContent = 'RONDA 01';
    ui.promptLabel.textContent = 'TU CONCEPTO';
    ui.promptIndex.textContent = '#01';
    ui.promptWord.textContent = 'LISTA';
    ui.promptHint.textContent = 'Marcá cuatro pulsos para empezar';
    ui.instruction.textContent = 'En el 1, agarrá el concepto. En el 3, buscá el remate.';
    ui.hit.disabled = true;
    showEmptyRhymes();
  }

  function confirmHit() {
    if (!state.rhymeRevealed || state.hitThisRound) return;
    state.hitThisRound = true;
    state.streak += 1;
    state.hits += 1;
    state.best = Math.max(state.best, state.streak);
    updateStats();
    saveProgress();
    ui.hit.disabled = true;
    ui.hit.innerHTML = 'REMATE GUARDADO <span>✓</span>';
    window.setTimeout(() => { ui.hit.innerHTML = '¡LA EMBOQUÉ! <span>↗</span>'; }, 1100);
    showToast('Una más para la racha. ¡Buen remate!');
  }

  function updateStats() {
    ui.streak.textContent = String(state.streak);
    ui.hits.textContent = String(state.hits);
    ui.best.textContent = String(state.best);
  }

  function setMode(mode) {
    if (!PROMPTS[mode]) return;
    state.mode = mode;
    document.body.classList.toggle('mode-double', mode === 'doble');
    ui.modeButtons.forEach((button) => {
      const active = button.dataset.mode === mode;
      button.classList.toggle('active', active);
      button.setAttribute('aria-pressed', String(active));
    });
    if (state.bpm) ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
    restartClockPhase();
  }

  function restartClockPhase() {
    if (!state.running) return;
    state.generation += 1;
    window.clearTimeout(state.timer);
    state.tickTimerIds.forEach((id) => window.clearTimeout(id));
    state.tickTimerIds.clear();
    state.tickNumber = 0;
    state.nextTickAt = performance.now() + 70;
    scheduleLoop(state.generation);
  }

  function stopClock() {
    state.running = false;
    state.generation += 1;
    window.clearTimeout(state.timer);
    state.tickTimerIds.forEach((id) => window.clearTimeout(id));
    state.tickTimerIds.clear();
    ui.beatBoxes.forEach((box) => box.classList.remove('active', 'sub-beat'));
    setTempoReady(Boolean(state.bpm));
  }

  function resetSession() {
    stopClock();
    state.tapTimes = [];
    state.intervals = [];
    state.bpm = null;
    state.roundNumber = 0;
    state.currentPrompt = null;
    state.rhymeRevealed = false;
    state.hitThisRound = false;
    state.streak = 0;
    state.hits = 0;
    ui.bpm.textContent = '—';
    ui.tempoCaption.textContent = 'Tocá al ritmo de tu base';
    ui.hit.innerHTML = '¡LA EMBOQUÉ! <span>↗</span>';
    renderEmptyPrompt();
    updateStats();
    saveProgress();
    showToast('Sesión reiniciada. El récord queda guardado.');
  }

  function pulseTapButton() {
    ui.tap.classList.add('pulse');
    window.setTimeout(() => ui.tap.classList.remove('pulse'), 110);
  }

  function toggleSound() {
    state.soundOn = !state.soundOn;
    if (state.soundOn) resumeAudio();
    updateSoundButton();
    showToast(state.soundOn ? 'Metrónomo sonoro activado.' : 'Metrónomo sonoro silenciado.');
  }

  function updateSoundButton() {
    ui.sound.classList.toggle('active', state.soundOn);
    ui.sound.setAttribute('aria-pressed', String(state.soundOn));
    ui.sound.setAttribute('aria-label', state.soundOn ? 'Silenciar metrónomo' : 'Activar metrónomo sonoro');
    ui.sound.title = state.soundOn ? 'Silenciar metrónomo' : 'Activar metrónomo sonoro';
  }

  function resumeAudio() {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextClass) return;
    try {
      if (!state.audio) state.audio = new AudioContextClass();
      if (state.audio.state === 'suspended') state.audio.resume();
    } catch (_) {
      // Visual timing remains available if Web Audio is unavailable.
    }
  }

  function scheduleClick(time, accented) {
    if (!state.audio || state.audio.state !== 'running') return;
    try {
      const oscillator = state.audio.createOscillator();
      const gain = state.audio.createGain();
      const start = state.audio.currentTime + Math.max(0, time - performance.now()) / 1000;
      oscillator.type = 'sine';
      oscillator.frequency.value = accented ? 880 : 590;
      gain.gain.setValueAtTime(0.0001, start);
      gain.gain.exponentialRampToValueAtTime(accented ? 0.11 : 0.055, start + 0.004);
      gain.gain.exponentialRampToValueAtTime(0.0001, start + 0.045);
      oscillator.connect(gain);
      gain.connect(state.audio.destination);
      oscillator.start(start);
      oscillator.stop(start + 0.05);
      oscillator.onended = () => { oscillator.disconnect(); gain.disconnect(); };
    } catch (_) {
      // A missed sound must not stop the visual beat scheduler.
    }
  }

  function showToast(message) {
    ui.toast.textContent = message;
    ui.toast.classList.add('show');
    window.clearTimeout(state.toastTimer);
    state.toastTimer = window.setTimeout(() => ui.toast.classList.remove('show'), 1900);
  }

  function handleYouTubeSubmit(event) {
    event.preventDefault();
    const media = parseYouTubeUrl(ui.url.value);
    if (!media) {
      ui.playerStatus.textContent = 'Ese link no parece un video o playlist compatible de YouTube.';
      ui.url.focus();
      return;
    }
    state.pendingMedia = media;
    ui.playerFrame.hidden = false;
    ui.playerStatus.textContent = media.type === 'playlist' ? 'Preparando playlist de YouTube…' : 'Preparando video de YouTube…';
    if (state.player) {
      try { state.player.destroy(); } catch (_) { /* Ignore stale player cleanup errors. */ }
      state.player = null;
    }
    ui.player.replaceChildren();
    loadYouTubeApi();
  }

  function parseYouTubeUrl(value) {
    const raw = String(value || '').trim();
    if (!raw || raw.length > 2048) return null;
    let url;
    try {
      url = new URL(/^[a-z][a-z\d+.-]*:/i.test(raw) ? raw : `https://${raw}`);
    } catch (_) {
      return null;
    }
    if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) return null;
    const host = url.hostname.toLowerCase().replace(/\.$/, '');
    const isYoutube = host === 'youtube.com' || host.endsWith('.youtube.com');
    const isShort = host === 'youtu.be';
    if (!isYoutube && !isShort) return null;
    const playlistId = url.searchParams.get('list');
    const validPlaylist = playlistId && /^[A-Za-z0-9_-]{10,120}$/.test(playlistId);
    let videoId = '';
    if (isShort) videoId = url.pathname.split('/').filter(Boolean)[0] || '';
    else if (url.pathname === '/watch') videoId = url.searchParams.get('v') || '';
    else {
      const match = url.pathname.match(/^\/(?:embed|shorts|live)\/([A-Za-z0-9_-]{11})(?:\/|$)/);
      if (match) videoId = match[1];
    }
    if (/^[A-Za-z0-9_-]{11}$/.test(videoId)) return { type: 'video', id: videoId };
    if (validPlaylist) return { type: 'playlist', id: playlistId };
    return null;
  }

  function loadYouTubeApi() {
    if (window.YT && window.YT.Player) {
      createYouTubePlayer();
      return;
    }
    if (state.apiState === 'loading') return;
    state.apiState = 'loading';
    const previousCallback = window.onYouTubeIframeAPIReady;
    window.onYouTubeIframeAPIReady = () => {
      if (typeof previousCallback === 'function') {
        try { previousCallback(); } catch (_) { /* Do not block this player. */ }
      }
      state.apiState = 'ready';
      createYouTubePlayer();
    };
    let script = document.querySelector('script[data-rapea-youtube-api]');
    if (!script) {
      script = document.createElement('script');
      script.src = 'https://www.youtube.com/iframe_api';
      script.async = true;
      script.dataset.rapeaYoutubeApi = 'true';
      script.onerror = () => {
        state.apiState = 'idle';
        ui.playerStatus.textContent = 'No se pudo conectar con YouTube. Podés seguir practicando sin el reproductor.';
      };
      document.head.append(script);
    }
    window.setTimeout(() => {
      if (state.apiState === 'loading') {
        state.apiState = 'idle';
        ui.playerStatus.textContent = 'YouTube tarda en responder o está bloqueado. Volvé a cargar el link para reintentar.';
      }
    }, 12000);
  }

  function createYouTubePlayer() {
    if (!state.pendingMedia || !window.YT || !window.YT.Player) return;
    state.apiState = 'ready';
    const media = state.pendingMedia;
    try {
      state.player = new window.YT.Player(ui.player, {
        width: '100%', height: '100%',
        playerVars: { autoplay: 0, controls: 1, playsinline: 1, rel: 0 },
        events: {
          onReady(event) {
            if (state.pendingMedia !== media) return;
            if (media.type === 'video') event.target.cueVideoById(media.id);
            else event.target.cuePlaylist({ listType: 'playlist', list: media.id, index: 0 });
            ui.playerStatus.textContent = 'Reproductor listo. Iniciá el video con sus controles; el TAP sigue independiente.';
          },
          onError(event) {
            const messages = {
              2: 'YouTube rechazó el identificador del video o playlist.',
              5: 'Este video no se puede reproducir en el reproductor HTML5.',
              100: 'El video no existe o no está disponible.',
              101: 'El dueño del video no permite reproducirlo en este reproductor.',
              150: 'El dueño del video no permite reproducirlo en este reproductor.',
              153: 'YouTube no pudo validar esta solicitud. Probá desde un sitio publicado.',
            };
            ui.playerStatus.textContent = messages[event.data] || 'YouTube no pudo cargar ese contenido; probá otro link.';
          },
        },
      });
      ui.playerStatus.textContent = 'Conectando con el reproductor oficial de YouTube…';
    } catch (_) {
      state.player = null;
      ui.playerStatus.textContent = 'No se pudo iniciar YouTube en este navegador. El entrenamiento sigue disponible.';
    }
  }

  function closeYouTubePlayer() {
    if (state.player) {
      try { state.player.destroy(); } catch (_) { /* Ignore stale player cleanup errors. */ }
    }
    state.player = null;
    state.pendingMedia = null;
    ui.player.replaceChildren();
    ui.playerFrame.hidden = true;
    ui.playerStatus.textContent = 'El beat suena por YouTube; el TAP marca un metrónomo independiente.';
  }
})();

