414:   function parseYouTubeUrl(value) {
415:     const raw = String(value || '').trim();
416:     if (!raw || raw.length > 2048) return null;
417:     let url;
418:     try {
419:       url = new URL(/^[a-z][a-z\d+.-]*:/i.test(raw) ? raw : `https://${raw}`);
420:     } catch (_) {
421:       return null;
422:     }
423:     if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password) return null;
424:     const host = url.hostname.toLowerCase().replace(/\.$/, '');
425:     const isYoutube = host === 'youtube.com' || host.endsWith('.youtube.com');
426:     const isShort = host === 'youtu.be';
427:     if (!isYoutube && !isShort) return null;
428:     const playlistId = url.searchParams.get('list');
429:     const validPlaylist = playlistId && /^[A-Za-z0-9_-]{10,120}$/.test(playlistId);
430:     let videoId = '';
431:     if (isShort) videoId = url.pathname.split('/').filter(Boolean)[0] || '';
432:     else if (url.pathname === '/watch') videoId = url.searchParams.get('v') || '';
433:     else {
434:       const match = url.pathname.match(/^\/(?:embed|shorts|live)\/([A-Za-z0-9_-]{11})(?:\/|$)/);
435:       if (match) videoId = match[1];
436:     }
437:     if (/^[A-Za-z0-9_-]{11}$/.test(videoId)) return { type: 'video', id: videoId };
438:     if (validPlaylist) return { type: 'playlist', id: playlistId };
439:     return null;
440:   }
